const fs = require('node:fs');
function put(file, id, priority) {
  const items = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : {};
  const updated = { priority };
  const next = { ...items, [id]: updated };
  fs.writeFileSync(file, JSON.stringify(next) + '\n');
}
function get(file, id) {
  const items = JSON.parse(fs.readFileSync(file, 'utf8'));
  return items[id] ?? null;
}
module.exports = { put, get };

