const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
function run(file, ...args) {
  const result = spawnSync(process.execPath, [path.join(__dirname, '..', 'cli.cjs'), file, ...args], {encoding:'utf8'});
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout);
}
test('new records persist independently', t => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'priority-store-'));
  t.after(() => fs.rmSync(dir, {recursive:true, force:true}));
  const file = path.join(dir, 'data.json');
  assert.deepEqual(run(file, 'put', 'alpha', '2'), {saved:true});
  assert.deepEqual(run(file, 'put', 'beta', '4'), {saved:true});
  assert.deepEqual(run(file, 'get', 'alpha'), {priority:2});
  assert.deepEqual(run(file, 'get', 'beta'), {priority:4});
});
test('updating a record persists its replacement and preserves other records', t => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'priority-store-'));
  t.after(() => fs.rmSync(dir, {recursive:true, force:true}));
  const file = path.join(dir, 'data.json');
  assert.deepEqual(run(file, 'put', 'alpha', '2'), {saved:true});
  assert.deepEqual(run(file, 'put', 'beta', '4'), {saved:true});
  assert.deepEqual(run(file, 'put', 'alpha', '5'), {saved:true});
  assert.deepEqual(run(file, 'get', 'alpha'), {priority:5});
  assert.deepEqual(run(file, 'get', 'beta'), {priority:4});
});

